param([Parameter(Mandatory=$true)][string]$SourcePath,[Parameter(Mandatory=$true)][string]$HeaderPath,[Parameter(Mandatory=$true)][string]$TestPath)
$ErrorActionPreference='Stop'
function A([bool]$x,[string]$m){if(!$x){throw $m}}
function O([string]$t,[string[]]$v,[string]$n){$p=-1;foreach($x in $v){$q=$t.IndexOf($x,$p+1);A ($q-gt$p) "$n $x";$p=$q}}
function V([string]$s,[string]$h,[string]$t){
 foreach($x in @('LOADER_PERSISTENT_WIRE_DETACHED','LOADER_PERSISTENT_WIRE_LOADED','LOADER_PERSISTENT_WIRE_RESIDUAL_ERROR','LOADER_PERSISTENT_WIRE_MALFORMED','LOADER_PERSISTENT_WIRE_SHORT','LOADER_PERSISTENT_WIRE_OVERFLOW','Input may be','unaligned','never retained or modified','LoaderClassifyPersistentStatus')){A ($h.Contains($x)) "header $x"}
 $d=$s.Substring($s.IndexOf('static int WireDiagnosticValid'),$s.IndexOf('static int WireHeaderValid')-$s.IndexOf('static int WireDiagnosticValid'));foreach($x in @('source == VMX_PERSISTENT_PUBLIC_DIAGNOSTIC_NONE','LOADER_PERSISTENT_INSTRUCTION_FAIL_VALID','LOADER_PERSISTENT_INSTRUCTION_FAIL_INVALID','error_valid <= 1u','error_valid || error == 0u')){A ($d.Contains($x)) "diagnostic $x"}
 $hh=$s.Substring($s.IndexOf('static int WireHeaderValid'),$s.IndexOf('static int WireRecordValid')-$s.IndexOf('static int WireHeaderValid'));foreach($x in @('FirstOperationStatus < LOADER_PERSISTENT_STATUS_INVARIANT','FirstOperationIndex >= h->ContextCount','FirstCleanupStatus < LOADER_PERSISTENT_STATUS_INVARIANT','FirstCleanupIndex >= h->ContextCount')){A ($hh.Contains($x)) "header invariant $x"}
 $r=$s.Substring($s.IndexOf('static int WireRecordValid'),$s.IndexOf('static int WireRecordLoaded')-$s.IndexOf('static int WireRecordValid'));foreach($x in @('(r->ResidualFlags & ~residual_flags) == 0u','(r->OwnedMask & ~UINT32_C(7)) == 0u','(r->ContextOwnedResources & ~UINT32_C(63)) == 0u','r->CleanupStatus >= LOADER_PERSISTENT_OPERATION_INVARIANT')){A ($r.Contains($x)) "record invariant $x"}
 $l=$s.Substring($s.IndexOf('static int WireRecordLoaded'),$s.IndexOf('LOADER_PERSISTENT_WIRE_CLASS LoaderClassifyPersistentStatus')-$s.IndexOf('static int WireRecordLoaded'));foreach($x in @('LOADER_PERSISTENT_CPU_ACTIVE','r->Flags == WIRE_FLAGS_LOADED','LOADER_PERSISTENT_OWNED_LOADED','LOADER_PERSISTENT_CONTEXT_RESOURCES_ALL','WIRE_RESIDUAL_REQUIRED','~WIRE_RESIDUAL_ALLOWED','LOADER_PERSISTENT_OPERATION_RESIDENT','PrimaryStatus == 0','CleanupStatus == 0','diagnostic == 0u')){A ($l.Contains($x)) "loaded $x"}
 $c=$s.Substring($s.IndexOf('LOADER_PERSISTENT_WIRE_CLASS LoaderClassifyPersistentStatus'),$s.IndexOf('LOADER_PERSISTENT_STATUS_PROOF LoaderValidateDetachedStatus')-$s.IndexOf('LOADER_PERSISTENT_WIRE_CLASS LoaderClassifyPersistentStatus'))
 A ($c-notmatch'(?i)windows.h|DeviceIoControl|OpenService|DeleteService|IOCTL|VMXON|VMLAUNCH|VMXOFF') 'pure classifier'
 O $c @('status_size < sizeof(h)','memcpy(&h,bytes,sizeof(h))','HeaderSize != sizeof(h)','RecordSize != sizeof(VMX_PERSISTENT_PUBLIC_CONTEXT_RECORD)','h.Reserved != 0u','ContextCount > (SIZE_MAX - sizeof(h))','required > UINT32_MAX','status_size < required','status_size != required','WireHeaderValid(&h)','ContextCount == 0u','for (i=0;i<h.ContextCount;i++)','memcpy(&r','SystemIndex != (uint32_t)i','WireRecordValid(&r)','for (j=0;j<i;j++)','memcpy(&previous','r.Group == previous.Group','WireRecordLoaded(&r)','LOADER_PERSISTENT_WIRE_LOADED') 'classifier'
 foreach($x in @('CanonicalLoadedStatus','Records[2]','Records[65]','65 CPU multi-group loaded','unaligned+1u','owner mask drift','resource mask drift','lifecycle range drift','operation status drift','fail-invalid drift','prepare-style header-only error is residual','VMX_PERSISTENT_PUBLIC_RESIDUAL_CR0','VMX_PERSISTENT_PUBLIC_RESIDUAL_CR4','EXPECT_RESIDUAL','LOADER_PERSISTENT_WIRE_OVERFLOW','HeaderSize=47u','RecordSize=71u','Header.Reserved=1u','SystemIndex=1u','Number=64u','OwnedMask|=8u','ContextOwnedResources|=64u','ResidualFlags|=(1u<<11)','CleanupStatus=-12','PrimarySource=1u')){A ($t.Contains($x)) "test $x"}
}
$s=[IO.File]::ReadAllText((Resolve-Path $SourcePath));$h=[IO.File]::ReadAllText((Resolve-Path $HeaderPath));$t=[IO.File]::ReadAllText((Resolve-Path $TestPath));V $s $h $t
foreach($m in @($s.Replace('memcpy(&h,bytes,sizeof(h));','h=*(const VMX_PERSISTENT_PUBLIC_STATUS_HEADER*)bytes;'),$s.Replace('required > UINT32_MAX','false'),$s.Replace('r.SystemIndex != (uint32_t)i','false'),$s.Replace('r.Group == previous.Group','false'),$s.Replace('(r->ResidualFlags & WIRE_RESIDUAL_REQUIRED) == WIRE_RESIDUAL_REQUIRED','true'),$s.Replace('(r->ResidualFlags & ~WIRE_RESIDUAL_ALLOWED) == 0u','true'),$s.Replace('r->PrimaryStatus == 0','true'),$s.Replace('h->FirstOperationStatus < LOADER_PERSISTENT_STATUS_INVARIANT','false'),$s.Replace('(r->OwnedMask & ~UINT32_C(7)) == 0u','true'),$s.Replace('(r->ContextOwnedResources & ~UINT32_C(63)) == 0u','true'),$s.Replace('(r->ResidualFlags & ~residual_flags) == 0u','true'),$s.Replace('r->CleanupStatus >= LOADER_PERSISTENT_OPERATION_INVARIANT','true'))){A ($m-ne$s) 'vacuous';$bad=$false;try{V $m $h $t}catch{$bad=$true};A $bad 'accepted mutation'}
'Verified pure V3F1 classifier: checked sizing, memcpy reads, canonical loaded ownership/residuals, diagnostics, identities, and mutations.'
